import{_ as e,o as s,c as t,ah as r}from"./chunks/framework.Yx0DUrwu.js";const m=JSON.parse('{"title":"测序方法与技术原理","description":"","frontmatter":{},"headers":[],"relativePath":"biology/sequencing-principles.md","filePath":"biology/sequencing-principles.md","lastUpdated":1778485541000}'),n={name:"biology/sequencing-principles.md"};function i(o,a,l,c,p,h){return s(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="测序方法与技术原理" tabindex="-1">测序方法与技术原理 <a class="header-anchor" href="#测序方法与技术原理" aria-label="Permalink to &quot;测序方法与技术原理&quot;">​</a></h1><p>测序方法的核心差异在于：它测的是哪一种分子、在哪个分辨率测、读长多长、是否保留空间位置、是否能同时读取多个模态。理解这些差异，比记住工具参数更重要。</p><h2 id="常见技术按问题分类" tabindex="-1">常见技术按问题分类 <a class="header-anchor" href="#常见技术按问题分类" aria-label="Permalink to &quot;常见技术按问题分类&quot;">​</a></h2><div class="check-grid"><article><strong>DNA-seq / WGS / WES</strong><span>读基因组变异、结构变异、拷贝数变化和克隆关系。</span></article><article><strong>bulk RNA-seq</strong><span>读样本平均表达，适合差异表达、通路和剪接分析。</span></article><article><strong>scRNA-seq</strong><span>读单细胞表达异质性，适合细胞类型、状态和轨迹问题。</span></article><article><strong>ATAC-seq / scATAC-seq</strong><span>读染色质开放区域，用于推断调控元件和转录因子活性。</span></article><article><strong>CITE-seq / multiome</strong><span>把 RNA、表面蛋白或染色质开放放在同一细胞里联合测量。</span></article><article><strong>空间转录组</strong><span>保留组织位置，把表达状态放回空间结构和细胞邻域。</span></article></div><h2 id="scrna-seq-的基本原理" tabindex="-1">scRNA-seq 的基本原理 <a class="header-anchor" href="#scrna-seq-的基本原理" aria-label="Permalink to &quot;scRNA-seq 的基本原理&quot;">​</a></h2><p>多数高通量 scRNA-seq 流程可以拆成五步：单细胞分隔、mRNA 捕获、反转录、细胞 barcode 和 UMI 标记、测序后按 barcode 还原表达矩阵。Tang 等人在 2009 年展示了单细胞 mRNA-seq 的早期路线，后续微流控和液滴技术让单细胞转录组进入高通量阶段 [1]。</p><div class="flow-strip"><span>分隔单细胞</span><span>捕获 mRNA</span><span>加入 barcode/UMI</span><span>建库测序</span><span>比对或伪比对</span><span>生成 count matrix</span><span>质控与过滤</span><span>下游分析</span></div><h2 id="umi-为什么重要" tabindex="-1">UMI 为什么重要 <a class="header-anchor" href="#umi-为什么重要" aria-label="Permalink to &quot;UMI 为什么重要&quot;">​</a></h2><p>UMI 用随机分子标签标记原始 RNA 分子，帮助区分 PCR 扩增副本和真实分子数。它不能消除所有偏倚，但能显著改善分子计数的可解释性。</p><h2 id="atac-seq-与染色质开放" tabindex="-1">ATAC-seq 与染色质开放 <a class="header-anchor" href="#atac-seq-与染色质开放" aria-label="Permalink to &quot;ATAC-seq 与染色质开放&quot;">​</a></h2><p>ATAC-seq 使用 Tn5 转座酶优先进入开放染色质区域，并把测序接头插入这些区域。Buenrostro 等人在 2013 年提出 ATAC-seq 后，它迅速成为低输入量染色质可及性分析的重要方法 [2]。单细胞 ATAC-seq 则把调控层面的异质性拆到单细胞分辨率。</p><h2 id="空间转录组" tabindex="-1">空间转录组 <a class="header-anchor" href="#空间转录组" aria-label="Permalink to &quot;空间转录组&quot;">​</a></h2><p>空间转录组回答“表达状态在组织中在哪里”。Stahl 等人 2016 年提出的 spatial transcriptomics 使用带空间条形码的阵列捕获组织切片中的 RNA [3]。这类方法牺牲或调整了某些分辨率、捕获效率和覆盖度，但换来了组织结构信息。</p><h2 id="多组学测序" tabindex="-1">多组学测序 <a class="header-anchor" href="#多组学测序" aria-label="Permalink to &quot;多组学测序&quot;">​</a></h2><p>CITE-seq 通过寡核苷酸标记抗体同时读取 RNA 和表面蛋白，适合免疫细胞注释 [4]。10x Multiome 等方法则把 RNA 和 ATAC 放在同一细胞中联合测量，适合调控解释。</p><div class="doc-callout warning"><strong>技术选择决定问题边界</strong><p>scRNA-seq 很适合发现细胞状态，但不擅长直接证明蛋白活性；空间转录组适合组织定位，但不同平台的单细胞分辨率差异很大；ATAC-seq 能提示调控潜力，但需要和表达、motif、footprint 等证据一起解释。</p></div><h2 id="自检问题" tabindex="-1">自检问题 <a class="header-anchor" href="#自检问题" aria-label="Permalink to &quot;自检问题&quot;">​</a></h2><ol><li>barcode 和 UMI 分别解决什么问题？</li><li>为什么 scRNA-seq count matrix 不是原始生物分子状态的完整复制？</li><li>ATAC-seq 的信号为什么可以反映染色质开放？</li><li>空间转录组和 dissociation-based scRNA-seq 各自失去了什么信息？</li></ol><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><p>[1] Tang, F. et al. mRNA-Seq whole-transcriptome analysis of a single cell. <em>Nature Methods</em> 6, 377-382 (2009). <a href="https://www.nature.com/articles/nmeth.1315" target="_blank" rel="noreferrer">Nature Methods</a></p><p>[2] Buenrostro, J. D. et al. Transposition of native chromatin for fast and sensitive epigenomic profiling of open chromatin. <em>Nature Methods</em> 10, 1213-1218 (2013). <a href="https://www.nature.com/articles/nmeth.2688" target="_blank" rel="noreferrer">Nature Methods</a></p><p>[3] Stahl, P. L. et al. Visualization and analysis of gene expression in tissue sections by spatial transcriptomics. <em>Science</em> 353, 78-82 (2016). <a href="https://www.science.org/doi/10.1126/science.aaf2403" target="_blank" rel="noreferrer">Science</a></p><p>[4] Stoeckius, M. et al. Simultaneous epitope and transcriptome measurement in single cells. <em>Nature Methods</em> 14, 865-868 (2017). <a href="https://www.nature.com/articles/nmeth.4380" target="_blank" rel="noreferrer">Nature Methods</a></p>',23)])])}const u=e(n,[["render",i]]);export{m as __pageData,u as default};
